<?php
declare(strict_types=1); namespace App\Http\Controllers\Classrooms; use App\Http\Controllers\Controller; use App\Http\Requests\Classrooms\{PromotionPreviewRequest,PromotionConfirmRequest}; use App\Models\{AcademicYear,Classroom,ClassroomPromotionBatch}; use App\Services\Classrooms\ClassroomPromotionService; use Illuminate\Http\RedirectResponse; use Illuminate\View\View;
class ClassroomPromotionController extends Controller {public function form():View{request()->user()->can('classrooms.promote')?:abort(403);return view('classrooms.promotions',['years'=>AcademicYear::latest('starts_at')->get(),'rooms'=>Classroom::with(['academicYear','gradeLevel'])->get()]);}public function preview(PromotionPreviewRequest $r,ClassroomPromotionService $s):View{$b=$s->preview($r->user(),$r->integer('source_academic_year_id'),$r->integer('target_academic_year_id'),$r->input('plans',[]));$b->load(['rows.student','rows.sourceClassroom.gradeLevel','rows.targetClassroom','sourceAcademicYear','targetAcademicYear']);return view('classrooms.promotion-preview',['batch'=>$b]);}public function confirm(PromotionConfirmRequest $r,ClassroomPromotionService $s):RedirectResponse{$b=ClassroomPromotionBatch::findOrFail($r->integer('batch_id'));$s->process($r->user(),$b);return redirect()->route('classrooms.promotions.result',$b)->with('success','Kenaikan kelas berhasil diproses.');}public function result(ClassroomPromotionBatch $batch):View{request()->user()->can('classrooms.promote')?:abort(403);return view('classrooms.promotion-result',['batch'=>$batch->load(['rows.student','sourceAcademicYear','targetAcademicYear'])]);}}
